/* C translation of Rob Hubbard's Commando (title) playroutine.
 *
 * Song data comes from commando_data.h, generated byte-for-byte from the
 * assembled original: SONG_DATA is the image starting at _songdata (track
 * lists, pattern pointer tables, patterns, instruments), so the 16-bit
 * pointers it holds are original addresses, resolved relative to SONG_ORG.
 */
#include <c64.h>
#include <stddef.h>
#include <stdint.h>

#include "commando_data.h"
#include "driver.h"

/* SID registers of the voice at byte offset `so` */
#define SIDREG(o) (((volatile uint8_t *)&SID)[o])
#define FQL (so + offsetof(struct __sid_voice, freq))
#define FQH (FQL + 1)
#define PWL (so + offsetof(struct __sid_voice, pw))
#define PWH (PWL + 1)
#define CTL (so + offsetof(struct __sid_voice, ctrl))
#define AD (so + offsetof(struct __sid_voice, ad))
#define SR (so + offsetof(struct __sid_voice, sr))

/* instrument record: 8 bytes */
enum { I_PWL, I_PWH, I_CTRL, I_AD, I_SR, I_VIB, I_PULSE, I_FX };
/* instrument fx flags */
enum { FX_DRUM = 1, FX_SKY = 2, FX_ARP = 4, FX_PWL = 8 };
/* note length byte: bits 0-4 length, 5 sustain, 6 legato, 7 instr follows */
enum { NL_LEN = 0x1f, NL_SUSTAIN = 0x20, NL_LEGATO = 0x40, NL_INSTR = 0x80 };
/* status: bit 6 = init pending, bit 7 = off (both: silence then off) */
enum { ST_INIT = 0x40, ST_OFF = 0x80 };

static uint8_t song[] = {SONG_DATA}; /* instrument pulse widths are modulated */
static const uint8_t sid[3] = {SID_OFFSETS};

/* The frequency table is followed by the per-voice state, as in the
 * original: vibrato reads the "next note" bytes at +3/+4, which for the
 * top notes run past the table into posoff. */
static struct {
  uint8_t freq[FREQ_LEN];
  uint8_t posoff[3], patoff[3], notec[3], notelen[3], ctrl[3], note[3],
      instr[3], pbend[3], pdelay[3], pdir[3], nfqh[3], nfql[3], trk[6];
} v = {.freq = {FREQ_TABLE}};
#define F(i) (((const uint8_t *)&v)[i])

static uint8_t status, tempo, tempoc, frc;

static uint8_t *at(uint8_t lo, uint8_t hi) {
  return song + (uint16_t)((lo | hi << 8) - SONG_ORG);
}

static uint8_t *instrument(uint8_t x) {
  return song + INS + (uint8_t)(v.instr[x] << 3);
}

static void putfreq(uint8_t so, uint8_t n) {
  uint8_t y = n << 1;
  SIDREG(FQH) = F(y + 1);
  SIDREG(FQL) = F(y);
}

/* Read the next note of voice x; returns 0 if the song stops. */
static uint8_t newnote(uint8_t x, uint8_t so) {
  const uint8_t *trk = at(v.trk[x], v.trk[x + 3]);
  uint8_t a, y, len, gate = 0xff;
  while ((a = trk[v.posoff[x]]) == 0xff) /* restart track */
    v.notec[x] = v.posoff[x] = v.patoff[x] = 0;
  if (a == 0xfe) { /* stop */
    status = ST_INIT | ST_OFF;
    return 0;
  }
  const uint8_t *pat = at(song[PATPL + a], song[PATPH + a]);
  v.pbend[x] = 0;
  y = v.patoff[x];
  v.notelen[x] = len = pat[y];
  v.notec[x] = len & NL_LEN;
  if (len & NL_LEGATO) {
    gate = 0xfe;
  } else {
    ++v.patoff[x];
    if (len & NL_INSTR) { /* instrument, or pitch bend if bit 7 */
      a = pat[++y];
      if (a & 0x80)
        v.pbend[x] = a;
      else
        v.instr[x] = a;
      ++v.patoff[x];
    }
    v.note[x] = a = pat[++y];
    putfreq(so, a);
    v.nfqh[x] = F((uint8_t)(a << 1) + 1);
    v.nfql[x] = F((uint8_t)(a << 1));
  }
  const uint8_t *in = instrument(x);
  SIDREG(CTL) = in[I_CTRL] & gate;
  SIDREG(PWL) = in[I_PWL];
  SIDREG(PWH) = in[I_PWH];
  SIDREG(AD) = in[I_AD];
  SIDREG(SR) = in[I_SR];
  v.ctrl[x] = in[I_CTRL];
  if (pat[++v.patoff[x]] == 0xff) { /* end of pattern */
    v.patoff[x] = 0;
    ++v.posoff[x];
  }
  return 1;
}

static void effects(uint8_t x, uint8_t so) {
  uint8_t *in = instrument(x);
  uint8_t fx = in[I_FX], pulse = in[I_PULSE], vib = in[I_VIB];
  uint8_t c = v.instr[x] >> 5 & 1; /* 6502 carry, consumed by FX_PWL */

  if (vib) { /* triangle 0..3..0 over 8 frames, depth (next - this) >> vib+1 */
    uint8_t vosc = frc & 7, y = v.note[x] << 1;
    if (vosc >= 4)
      vosc ^= 7;
    uint16_t f = F(y + 1) << 8 | F(y);
    uint16_t dif = (F(y + 3) << 8 | F(y + 4)) - f;
    do
      dif >>= 1;
    while ((int8_t)--vib >= 0);
    c = (v.notelen[x] & NL_LEN) >= 6;
    if (c)
      while (vosc--) {
        uint16_t s = f + dif;
        c = s < f;
        f = s;
      }
    SIDREG(FQL) = f;
    SIDREG(FQH) = f >> 8;
  }

  if (fx & FX_PWL) {
    SIDREG(PWL) = in[I_PWL] += pulse + c;
  } else if (pulse && (int8_t)--v.pdelay[x] < 0) { /* pulse sweep $800-$e00 */
    uint8_t rate = pulse & 0xe0;
    uint16_t pw = in[I_PWH] << 8 | in[I_PWL];
    v.pdelay[x] = pulse & 0x1f;
    if (!v.pdir[x]) {
      pw += rate;
      if ((pw >> 8 & 0xf) == 0xe)
        ++v.pdir[x];
    } else {
      pw -= rate;
      if ((pw >> 8 & 0xf) == 8)
        --v.pdir[x];
    }
    SIDREG(PWH) = in[I_PWH] = pw >> 8 & 0xf;
    SIDREG(PWL) = in[I_PWL] = pw;
  }

  uint8_t pb = v.pbend[x];
  if (pb) { /* bit 0: down, bits 1-6: rate */
    uint16_t nf = v.nfqh[x] << 8 | v.nfql[x];
    nf = pb & 1 ? nf - (pb & 0x7e) : nf + (pb & 0x7e);
    SIDREG(FQL) = v.nfql[x] = nf;
    SIDREG(FQH) = v.nfqh[x] = nf >> 8;
  }

  if ((fx & FX_DRUM) && v.nfqh[x] && v.notec[x]) {
    uint8_t ctl = 0; /* first frame noise, then falling pitch */
    if ((uint8_t)((v.notelen[x] & NL_LEN) - 1) >= v.notec[x]) {
      SIDREG(FQH) = v.nfqh[x]--;
      ctl = v.ctrl[x] & 0xfe;
    }
    if (!ctl) {
      SIDREG(FQH) = v.nfqh[x];
      ctl = 0x80;
    }
    SIDREG(CTL) = ctl;
  }

  if ((fx & FX_SKY) && (v.notelen[x] & NL_LEN) >= 3 && (frc & 1) &&
      v.nfqh[x]) { /* rising pitch every other frame */
    SIDREG(FQH) = v.nfqh[x];
    v.nfqh[x] += 2;
  }

  if (fx & FX_ARP) /* octave arpeggio */
    putfreq(so, v.note[x] + (frc & 1 ? 12 : 0));
}

void tune_play(void) {
  ++frc;
  if (status & ST_OFF) {
    if (status & ST_INIT) {
      SID.v1.ctrl = 0;
      SID.v2.ctrl = 0;
      SID.v3.ctrl = 0;
      SID.amp = 0xf;
      status = ST_OFF;
    }
    return;
  }
  if (status & ST_INIT) {
    frc = 0;
    for (uint8_t x = 0; x < 3; ++x)
      v.posoff[x] = v.patoff[x] = v.notec[x] = v.note[x] = 0;
    status = 0;
  }
  if ((int8_t)--tempoc < 0)
    tempoc = tempo;
  for (int8_t x = 2; x >= 0; --x) {
    uint8_t so = sid[x];
    if (tempoc == tempo) {
      if ((int8_t)--v.notec[x] < 0) {
        if (!newnote(x, so))
          return;
        continue;
      }
      if (!(v.notelen[x] & NL_SUSTAIN) && !v.notec[x]) { /* hard restart */
        SIDREG(CTL) = v.ctrl[x] & 0xfe;
        SIDREG(AD) = 0;
        SIDREG(SR) = 0;
      }
    }
    effects(x, so);
  }
}

void tune_init(uint8_t s) {
  uint8_t i = s * 6;
  tempo = song[SONGTEMPOS + s];
  for (uint8_t j = 0; j < 6; ++j)
    v.trk[j] = song[SONGPTRS + i++];
  SID.v1.ctrl = 0;
  SID.v2.ctrl = 0;
  SID.v3.ctrl = 0;
  SID.amp = 0xf;
  status = ST_INIT;
}
